mapper.select:
/* isry.couns.mngr.mntrngReprtsMng.mapper.MntrngReprtsMngMapper.selectMntrngReprtsList - 개발지원팀 이태호 */ SELECT A.MNTRNG_NO AS MNTRNG_NO ,A.WRTR_ID AS WRTR_ID ,A.CRT_YMD AS CRT_YMD ,C##RG.DEC_B64(C.FLNM_ENCPT) AS WRTR_NM ,COUNT(*) OVER() AS TOTAL_COUNT FROM AYC400 A, SAA200 B, SCA100 C WHERE 1 = 1 AND A.WRTR_ID = B.USER_ID AND B.ENFSN_NO = C.ENFSN_NO AND A.DEL_YN = 'N'
AND C.FLNM_ENCPT = C##RG.ENC_B64(#{wrtrNmEncpt})
AND A.CRT_YMD BETWEEN #{startDt} AND #{endDt}
ORDER BY A.CRT_YMD DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY /** 페이징 처리 **/

WITH VIEW_CNSLTNT_WORK_SCHDL AS (
) , VIEW_VCATN_APLY_HISTB AS (
) SELECT /* SQL-ID : isry.couns.mngr.mntrngReprtsMng.mapper.MntrngReprtsMngMapper.selectCnsltntWorkSchdlList : 상담사 근무일정 및 휴가 조회 */ WL.WORK_YMD /* 근무일자 */ , WL.BGNG_HR /* 시작시간 */ , WL.END_HR /* 종료시간 */ , TO_CHAR(WL.WORK_BGNG_DT, 'YYYY-MM-DD HH24:MI:SS') AS WORK_BGNG_DT /* 근무시작일시 */ , TO_CHAR(WL.WORK_END_DT, 'YYYY-MM-DD HH24:MI:SS') AS WORK_END_DT /* 근무종료일시 */ , WL.HR_WORK_TYPE_SE_CD1 /* 시간근무유형구분코드1 */ , WL.HR_WORK_TYPE_SE_CD2 /* 시간근무유형구분코드2 */ , WL.CNSLTNT_ID /* 상담사아이디 */ , WL.TASKWK_TYPE_DEPT_CD AS OGDP_DEPT_CD /* 소속부서코드 */ , WR.TASKWK_REPRTS_INDEX_SN /* 업무보고서색인일련번호 */ , CASE WHEN ( SELECT COUNT(*) FROM VIEW_VCATN_APLY_HISTB VA WHERE VA.USER_ID = WL.CNSLTNT_ID AND WL.WORK_YMD BETWEEN VA.VCATN_BGNG_YMD AND VA.VCATN_END_YMD ) > 0 THEN '휴가' ELSE '' END AS CHTT_OPEN_HR_CN /* 채팅오픈시간내용 */ FROM VIEW_CNSLTNT_WORK_SCHDL WL , AYC300 WR /* 업무보고서 */ WHERE WL.WORK_YMD = #{WORK_YMD} AND WL.CNSLTNT_ID = WR.CNSLTNT_ID(+) AND WL.WORK_YMD = WR.WORK_YMD(+) ORDER BY WL.BGNG_HR ASC

mapper.insert:
/* SQL-ID : isry.couns.mngr.mntrngReprtsMng.mapper.MntrngReprtsMngMapper.insertMntrngReprtsData : 모니터링보고서 데이터 등록 */ INSERT INTO AYC410 ( MNTRNG_NO /* 모니터링번호 */ , MNTRNG_DATAA_NO /* 모니터링데이터번호 */ , WORK_YMD /* 근무일자 */ , JOB_BGNG_TM /* 작업시작시각 */ , JOB_END_TM /* 작업종료시각 */ , TASKWK_RPT_CNSLTNT_ID /* 업무보고상담사아이디 */ , TASKWK_REPRTS_INDEX_SN /* 업무보고서색인일련번호 */ , CHTT_OPEN_HR_CN /* 채팅오픈시간내용 */ , CHTT_OPEN_DT /* 채팅오픈일시 */ , CHTT_END_TM /* 채팅종료시각 */ , CHTT_END_DT /* 채팅종료일시 */ , LVFFC_PRCS_DT /* 퇴근처리일시 */ , CHTT_UNESTA_TM /* 채팅미개설시각 */ , CONSTT_BREAK_HR /* 상담자휴게시간 */ , OGDP_DEPT_CD /* 소속부서코드 */ , FRST_RGTR_ID /* 최초등록자아이디 */ , FRST_REG_DT /* 최초등록일시 */ , LAST_MDFR_ID /* 최종수정자아이디 */ , LAST_MDFCN_DT /* 최종수정일시 */ )
VALUES
( #{model.MNTRNG_NO} /* 모니터링번호 */ , AYC410_SQ01.NEXTVAL /* 모니터링데이터번호 */ , #{model.WORK_YMD} /* 근무일자 */ , #{model.BGNG_HR} /* 작업시작시각 */ , #{model.END_HR} /* 작업종료시각 */ , #{model.CNSLTNT_ID} /* 업무보고상담사아이디 */ , #{model.TASKWK_REPRTS_INDEX_SN} /* 업무보고서색인일련번호 */ , #{model.CHTT_OPEN_HR_CN} /* 채팅오픈시간내용 */ , TO_DATE(#{model.CHTT_OPEN_DT}, 'YYYY-MM-DD HH24:MI:SS') /* 채팅오픈일시 */ , #{model.CHTT_END_TM} /* 채팅종료시각 */ , TO_DATE(#{model.CHTT_END_DT}, 'YYYY-MM-DD HH24:MI:SS') /* 채팅종료일시 */ , #{model.LVFFC_PRCS_DT} /* 퇴근처리일시 */ , #{model.CHTT_UNESTA_TM} /* 채팅미개설시각 */ , #{model.CONSTT_BREAK_HR} /* 상담자휴게시간 */ , #{model.OGDP_DEPT_CD} /* 소속부서코드 */ , #{model.RGTR_ID} /* 최초등록자아이디 */ , SYSDATE /* 최초등록일시 */ , #{model.RGTR_ID} /* 최종수정자아이디 */ , SYSDATE /* 최종등록일시 */ )

mapper.update:

/* isry.couns.mngr.mntrngReprtsMng.mapper.MntrngReprtsMngMapper.UpdateTASKWKREPRTSINDEXSN - 개발지원팀 이태호  */
UPDATE AYC410 /* 일간 모니터링 보고서 데이터 */
    SET TASKWK_REPRTS_INDEX_SN      = #{TASKWK_REPRTS_INDEX_SN} 
      , LAST_MDFR_ID                = #{LAST_MDFR_ID}
      , LAST_MDFCN_DT               = SYSDATE              
    WHERE MNTRNG_NO                 = #{MNTRNG_NO}
      AND TASKWK_RPT_CNSLTNT_ID     = #{TASKWK_RPT_CNSLTNT_ID}

mapper.select:
/* isry.couns.mngr.mntrngReprtsMng.mapper.MntrngReprtsMngMapper.selectWorkAltMntCrtYmdCheckList  */
SELECT CRT_YMD  AS CRT_YMD
  FROM AYC400 
 WHERE DEL_YN = 'N'     


   AND CRT_YMD = #{CRT_YMD}

mapper.delete:

/* SQL-ID : isry.couns.mngr.mntrngReprtsMng.mapper.MntrngReprtsMngMapper.deleteMntrngReprts : 모니터링 보고서 삭제 */
DELETE FROM AYC400              /* 일간 모니터링 보고서 */
WHERE MNTRNG_NO = #{MNTRNG_NO}  /* 모니터링번호 */


/* SQL-ID : isry.couns.mngr.mntrngReprtsMng.mapper.MntrngReprtsMngMapper.deleteMntrngReprtsData : 모니터링 보고서 데이터 삭제 */
DELETE FROM AYC410              /* 일간 모니터링 보고서 데이터 */
WHERE MNTRNG_NO = #{MNTRNG_NO}  /* 모니터링번호 */
